package org.mahoyo.port;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.content.res.Configuration;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import org.json.JSONObject;
import java.util.Locale;
/** First-run installer. A ready installation goes directly to the player without Steam initialization. */
public final class InstallActivity extends Activity implements InstallService.Observer {
 private static final int PATCH=502;
 private Installation installation;private InstallService service;private boolean bound=false,owned=false,ready=false;private String screen="";
 private LinearLayout panel;private TextView progressText,steamInfo;private ProgressBar progress;private EditText username,password,guard;private ImageView qrView;private Button qrLanToggle,qrSteamOpen;private TextView qrLanInfo;private String shownQr="";
 private final ServiceConnection connection=new ServiceConnection(){@Override public void onServiceConnected(ComponentName name,IBinder binder){service=((InstallService.LocalBinder)binder).service();screen="";service.observe(InstallActivity.this);}@Override public void onServiceDisconnected(ComponentName name){service=null;screen="";render();}};
 @Override public void onCreate(Bundle state){super.onCreate(state);if(state==null&&Intent.ACTION_MAIN.equals(getIntent().getAction())&&!getIntent().getBooleanExtra("manage",false))AppUpdates.beginLaunch();installation=new Installation(this);systemBars();
  try{JSONObject record=installation.read();owned=record.optBoolean("owned");ready=owned&&record.optBoolean("ready")&&installation.dataAvailable();if(ready&&!getIntent().getBooleanExtra("manage",false)){installation.syncLanguage(record);play();return;}}catch(Exception error){showFatal(error.getMessage());return;}
  FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0xff0b1423);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(24),dp(22),dp(24),dp(28));FrameLayout center=new FrameLayout(this);center.addView(panel,new FrameLayout.LayoutParams(Math.min(getResources().getDisplayMetrics().widthPixels,dp(700)),-2,Gravity.TOP|Gravity.CENTER_HORIZONTAL));scroll.addView(center);root.addView(scroll,new FrameLayout.LayoutParams(-1,-1));setContentView(root);installationInsets(root);root.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{if(r-l!=or-ol){FrameLayout.LayoutParams params=(FrameLayout.LayoutParams)panel.getLayoutParams();params.width=Math.min(Math.max(0,r-l-root.getPaddingLeft()-root.getPaddingRight()),dp(700));panel.setLayoutParams(params);}});
  bound=bindService(new Intent(this,InstallService.class),connection,BIND_AUTO_CREATE);render();
 }
 private void systemBars(){Window window=getWindow();window.clearFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);window.getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LAYOUT_STABLE);window.setStatusBarColor(0xff0b1423);window.setNavigationBarColor(0xff0b1423);if(Build.VERSION.SDK_INT>=30){window.setDecorFitsSystemWindows(false);WindowInsetsController bars=window.getInsetsController();if(bars!=null){bars.show(WindowInsets.Type.systemBars());bars.setSystemBarsAppearance(0,WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS);}}window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 private void installationInsets(View root){root.setOnApplyWindowInsetsListener((view,insets)->{int l,t,r,b;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets safe=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());l=safe.left;t=safe.top;r=safe.right;b=safe.bottom;}else{l=insets.getSystemWindowInsetLeft();t=insets.getSystemWindowInsetTop();r=insets.getSystemWindowInsetRight();b=insets.getSystemWindowInsetBottom();}view.setPadding(l,t,r,b);return insets;});root.requestApplyInsets();}
 static String stageLabel(Context context,String stage){int id;switch(stage){case "connecting":id=R.string.setup_connecting;break;case "authenticating":id=R.string.setup_authenticating;break;case "ownership":id=R.string.setup_ownership;break;case "downloading":id=R.string.setup_downloading;break;case "verifying":id=R.string.setup_verifying;break;case "preparing":id=R.string.setup_preparing;break;case "importing":id=R.string.setup_importing;break;case "mobile":id=R.string.setup_mobile;break;case "qr":id=R.string.setup_qr;break;case "guard":id=R.string.setup_guard;break;case "ready":id=R.string.setup_ready;break;default:id=R.string.setup_choose;}return context.getString(id);}
 @Override public void changed(){runOnUiThread(this::render);}
 private void render(){if(panel==null)return;String stage=service==null?"choose":service.stage;
  if(screen.equals(stage)&&!stage.equals("error")&&!stage.equals("guard")){updateProgress();return;}
  try{JSONObject record=installation.read();owned=record.optBoolean("owned");ready=owned&&record.optBoolean("ready")&&installation.dataAvailable();}catch(Exception e){showFatal(e.getMessage());return;}
  screen=stage;panel.removeAllViews();progress=null;progressText=null;steamInfo=null;qrView=null;qrLanToggle=null;qrSteamOpen=null;qrLanInfo=null;shownQr="";
  heading();space(18);
  if(service==null){panel.addView(text(getString(R.string.setup_preparing),16,0xffdce6f3));return;}
  if(stage.equals("error")){panel.addView(text(getString(R.string.setup_failure),19,0xffedf3fa));panel.addView(text(service.error,14,0xffc5d2e2));space(12);button(service.retryAction==InstallRetry.OPTIONS?R.string.setup_back_install:R.string.setup_retry,this::retry);if(ready)emphasize(button(R.string.setup_play,this::play));return;}
  if(service.busy()){
   panel.addView(text(stageLabel(this,stage),18,0xffedf3fa));
   if(stage.equals("qr")){panel.addView(text(getString(R.string.setup_qr_guide),15,0xffb7cce1));qrLanControls();qrView=new ImageView(this);qrView.setScaleType(ImageView.ScaleType.FIT_CENTER);LinearLayout.LayoutParams qrParams=new LinearLayout.LayoutParams(-1,dp(240));qrParams.topMargin=dp(12);panel.addView(qrView,qrParams);}
   else if(stage.equals("guard")){if(service.incorrect)panel.addView(text(getString(R.string.setup_guard_wrong),14,0xffd5b887));guard=input(getString(R.string.setup_guard),InputType.TYPE_CLASS_TEXT);button(R.string.setup_submit,()->service.submitGuard(guard.getText().toString()));}
   else if(!stage.equals("mobile")){progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);panel.addView(progress,new LinearLayout.LayoutParams(-1,dp(12)));progressText=text("",14,0xffb8c9dd);panel.addView(progressText);}
   space(18);button(R.string.setup_cancel,()->service.cancel());updateProgress();return;
  }
  if(!owned){loginForm();return;}
  boolean steamInstalled=false,patchApplied=false;try{JSONObject record=installation.read();steamInstalled=ready&&record.optString("backend").equals("steam");patchApplied=steamInstalled&&record.optString("edition").equals("korean");}catch(Exception e){showFatal(e.getMessage());return;}
  boolean promotePatch=steamInstalled&&getResources().getConfiguration().getLocales().get(0).getLanguage().equals("ko");
  if(ready){panel.addView(text(getString(R.string.setup_offline),15,0xffb7cce1));emphasize(button(R.string.setup_play,this::play));if(promotePatch)patchButton(true,patchApplied);space(20);}else{panel.addView(text(getString(R.string.setup_missing),15,0xffb7cce1));}
  panel.addView(text(getString(ready?R.string.setup_manage:R.string.setup_choose),20,0xffedf3fa));space(8);
  Button primary=button(ready?(steamInstalled?R.string.setup_steam_installed:R.string.setup_ready):R.string.setup_steam,()->{if(!service.busy()&&service!=null){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},11);if(!serviceConnected()){loginFormScreen();return;}service.download();}});
  if(ready)disable(primary);else emphasize(primary);
  if(!ready){steamInfo=text("",14,0xff9cb2ca);panel.addView(steamInfo);updateProgress();String patchHint=getString(R.string.setup_patch_hint);if(!patchHint.isEmpty())panel.addView(text(patchHint,14,0xff9cb2ca));}
  if(steamInstalled&&!promotePatch){space(18);patchButton(false,patchApplied);}
 }
 private void disable(Button view){view.setEnabled(false);view.setTextColor(0xff788798);GradientDrawable fill=new GradientDrawable();fill.setColor(0xff1b2838);fill.setCornerRadius(dp(7));view.setBackground(fill);}
 private void emphasize(Button view){view.setTextSize(17);view.setTypeface(null,Typeface.BOLD);GradientDrawable fill=new GradientDrawable();fill.setColor(0xff39749d);fill.setCornerRadius(dp(7));view.setBackground(fill);view.getLayoutParams().height=dp(56);}
 private void patchButton(boolean highlighted,boolean applied){Button patch=button(applied?R.string.setup_patch_installed:R.string.setup_patch,()->{Intent choose=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(choose,PATCH);});if(applied)disable(patch);else if(highlighted){GradientDrawable fill=new GradientDrawable();fill.setColor(0xff315a78);fill.setStroke(dp(1),0xff6591b0);fill.setCornerRadius(dp(7));patch.setBackground(fill);}if(!applied)panel.addView(text(getString(R.string.setup_patch_info),14,0xff9cb2ca));}
 private void qrLanControls(){
  qrLanToggle=button(R.string.setup_qr_lan_start,()->service.toggleQrLan());LinearLayout.LayoutParams params=(LinearLayout.LayoutParams)qrLanToggle.getLayoutParams();panel.removeView(qrLanToggle);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(qrLanToggle,new LinearLayout.LayoutParams(0,-1,1));
  ImageButton help=new ImageButton(this);help.setImageDrawable(new IconDrawable("help"));help.setContentDescription(getString(R.string.setup_qr_lan_title));help.setBackgroundColor(Color.TRANSPARENT);help.setPadding(dp(12),dp(12),dp(12),dp(12));help.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(R.string.setup_qr_lan_title).setMessage(getString(R.string.setup_qr_lan_help,getString(R.string.setup_qr_lan_start),getString(R.string.setup_steam_authenticator))).setPositiveButton(android.R.string.ok,null).show());row.addView(help,new LinearLayout.LayoutParams(dp(48),dp(48)));panel.addView(row,params);
  qrLanInfo=text("",14,0xffb7cce1);qrLanInfo.setTextIsSelectable(true);panel.addView(qrLanInfo);qrSteamOpen=button(R.string.setup_steam_authenticator,this::openSteamAuthenticator);
 }
 private void openSteamAuthenticator(){if(service==null||!service.stage.equals("qr")||service.qrChallenge.isEmpty())return;try{SteamQr.encode(service.qrChallenge,128);startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(service.qrChallenge)).setPackage("com.valvesoftware.android.steam.community"));}catch(Exception unavailable){Toast.makeText(this,R.string.setup_steam_app_missing,Toast.LENGTH_LONG).show();}}
 private boolean serviceConnected(){return service!=null&&service.connectedForDownload();}
 private void retry(){int action=service.retryAction;service.cancel();screen="";if(action==InstallRetry.QR)service.loginQr();else if(action==InstallRetry.PASSWORD)loginFormScreen();else render();}
 private void loginFormScreen(){screen="login";panel.removeAllViews();heading();panel.addView(text(getString(R.string.setup_relogin),15,0xffb7cce1));loginForm();}
 private void loginForm(){button(R.string.setup_qr,()->{if(service!=null)service.loginQr();});space(12);panel.addView(text(getString(R.string.setup_intro),15,0xffb7cce1));space(12);username=input(getString(R.string.setup_user),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD);password=passwordInput();button(R.string.setup_login,()->{if(service==null||username.getText().toString().trim().isEmpty()||password.length()==0)return;char[] secret=new char[password.length()];password.getText().getChars(0,password.length(),secret,0);String account=username.getText().toString();password.setText("");service.login(account,secret);});}
 private void updateProgress(){if(service==null)return;if(qrView!=null&&!service.qrChallenge.equals(shownQr)){try{shownQr=service.qrChallenge;com.google.zxing.common.BitMatrix matrix=SteamQr.encode(shownQr,dp(240));int w=matrix.getWidth(),h=matrix.getHeight();int[] pixels=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)pixels[y*w+x]=matrix.get(x,y)?Color.BLACK:Color.WHITE;qrView.setImageBitmap(android.graphics.Bitmap.createBitmap(pixels,w,h,android.graphics.Bitmap.Config.ARGB_8888));}catch(Exception error){qrView.setImageDrawable(null);showFatal(error.getMessage());}}if(qrLanToggle!=null){qrLanToggle.setText(service.qrLanStarting?R.string.setup_qr_lan_starting:service.qrLanUrl.isEmpty()?R.string.setup_qr_lan_start:R.string.setup_qr_lan_stop);qrLanToggle.setEnabled(!service.qrLanStarting);String info=!service.qrLanError.isEmpty()?service.qrLanError:service.qrLanUrl.isEmpty()?"":getString(R.string.setup_qr_lan_address,service.qrLanUrl);qrLanInfo.setText(info);qrLanInfo.setVisibility(info.isEmpty()?View.GONE:View.VISIBLE);qrSteamOpen.setVisibility(service.qrLanUrl.isEmpty()?View.GONE:View.VISIBLE);}if(progress!=null){progress.setIndeterminate(service.total<=0);if(service.total>0){progress.setMax(1000);progress.setProgress((int)(Math.min(1,service.fraction)*1000));}}if(progressText!=null&&service.stage.equals("downloading"))progressText.setText(getString(R.string.setup_transfer_info,service.fraction*100,service.transfer.received/1e9,service.transfer.unpacked/1e9,service.transfer.bytesPerSecond(SystemClock.elapsedRealtime())/1e6,service.estimatedInstall/1e9));else if(progressText!=null)progressText.setText(service.total>0?String.format(Locale.getDefault(),"%.1f%% · %.2f / %.2f GB",service.fraction*100,service.done/1e9,service.total/1e9):service.done>0?String.format(Locale.getDefault(),"%.2f GB",service.done/1e9):"");if(steamInfo!=null){java.io.File storage=getExternalFilesDir(null);steamInfo.setText(getString(R.string.setup_steam_info,String.format(Locale.getDefault(),"%.1f",service.estimatedInstall/1e9))+(service.estimatedDownload>0?String.format(Locale.getDefault(),"\n↓ %.2f GB",service.estimatedDownload/1e9):"")+"\n"+getString(R.string.setup_available,storage==null?0:storage.getUsableSpace()/1e9));}}

 private void play(){try{if(!installation.ready()||!installation.dataAvailable())throw new IllegalStateException(getString(R.string.setup_missing));installation.syncLanguage(installation.read());if(service!=null)service.disconnect();startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();}catch(Exception error){showFatal(error.getMessage());}}
 private void showFatal(String message){new AlertDialog.Builder(this).setTitle(R.string.setup_failure).setMessage(message).setPositiveButton(android.R.string.ok,(d,n)->finish()).show();}
 private EditText passwordInput(){
  EditText field=input(getString(R.string.setup_password),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);field.setSaveEnabled(false);field.setAutofillHints(View.AUTOFILL_HINT_PASSWORD);field.setTransformationMethod(android.text.method.PasswordTransformationMethod.getInstance());
  LinearLayout.LayoutParams params=(LinearLayout.LayoutParams)field.getLayoutParams();panel.removeView(field);FrameLayout row=new FrameLayout(this);field.setPadding(field.getPaddingLeft(),field.getPaddingTop(),field.getPaddingRight()+dp(52),field.getPaddingBottom());row.addView(field,new FrameLayout.LayoutParams(-1,-1));
  ImageButton eye=new ImageButton(this);eye.setImageDrawable(new IconDrawable("show"));eye.setContentDescription(getString(R.string.setup_password_show));eye.setBackgroundColor(Color.TRANSPARENT);eye.setPadding(dp(12),dp(12),dp(12),dp(12));row.addView(eye,new FrameLayout.LayoutParams(dp(48),dp(48),Gravity.END|Gravity.CENTER_VERTICAL));
  eye.setOnClickListener(v->{int start=field.getSelectionStart(),end=field.getSelectionEnd();boolean reveal=field.getTransformationMethod() instanceof android.text.method.PasswordTransformationMethod;field.setTransformationMethod(reveal?null:android.text.method.PasswordTransformationMethod.getInstance());if(start>=0&&end>=0)field.setSelection(Math.min(start,field.length()),Math.min(end,field.length()));eye.setImageDrawable(new IconDrawable(reveal?"hide":"show"));eye.setContentDescription(getString(reveal?R.string.setup_password_hide:R.string.setup_password_show));});
  panel.addView(row,params);return field;
 }
 private EditText input(String hint,int type){EditText field=new EditText(this);field.setTextColor(0xffedf3fa);field.setHintTextColor(0xff91a6bf);field.setHint(hint);field.setSingleLine(true);field.setInputType(type);field.setTextSize(16);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,dp(52));params.topMargin=dp(10);panel.addView(field,params);return field;}
 private TextView text(String value,int size,int color){TextView view=new TextView(this);view.setText(value);view.setTextSize(size);view.setTextColor(color);view.setPadding(0,dp(6),0,dp(6));view.setLineSpacing(dp(3),1);return view;}
 private Button button(int label,Runnable action){Button button=new Button(this);button.setText(label);button.setTextSize(15);button.setTextColor(Color.WHITE);button.setAllCaps(false);button.setStateListAnimator(null);button.setBackgroundTintList(null);GradientDrawable fill=new GradientDrawable();fill.setColor(0xff284563);fill.setCornerRadius(dp(7));button.setBackground(fill);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,dp(48));params.topMargin=dp(10);params.bottomMargin=dp(4);panel.addView(button,params);button.setOnClickListener(v->action.run());return button;}
 private void heading(){TextView title=text(getString(R.string.app_name)+" "+getString(R.string.setup_unofficial),22,0xffedf3fa);title.setTypeface(null,Typeface.BOLD);title.setSingleLine(true);title.setAutoSizeTextTypeUniformWithConfiguration(12,22,1,android.util.TypedValue.COMPLEX_UNIT_SP);panel.addView(title);}

 private void space(int size){panel.addView(new android.view.View(this),new LinearLayout.LayoutParams(1,dp(size)));}
 private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null||service==null)return;Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}if(request==PATCH)service.importPatch(uri);}
 @Override public void onConfigurationChanged(Configuration config){super.onConfigurationChanged(config);systemBars();}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus&&panel!=null)AppUpdates.focused(this);}
 @Override protected void onPostResume(){super.onPostResume();if(panel!=null)AppUpdates.launch(this);}
 @Override protected void onDestroy(){AppUpdates.detach(this);if(service!=null)service.observe(null);if(bound)unbindService(connection);super.onDestroy();}
}
